/**
 * Coupon Types — Sawaa Dashboard
 *
 * Response shapes are DERIVED from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`).
 *
 * Money: `discountValue` and `minOrderAmt` are Prisma `Decimal`s (decimal
 * strings on the wire); `discountValue` carries a raw percent for PERCENTAGE
 * coupons and halalas for FIXED ones. Query and payload types stay local.
 */

import type { components } from "@/lib/types/api.generated"
import type { PaginatedQuery } from "./common"

type Schemas = components["schemas"]

/* ─── Entities (derived from OpenAPI) ─── */

/** One persisted coupon (`CouponRecordDto`) — list, detail, create, update. */
export type Coupon = Schemas["CouponRecordDto"]

/** `GET /dashboard/finance/coupons` envelope (`CouponListResponseDto`). */
export type CouponListPage = Schemas["CouponListResponseDto"]

/** `POST /dashboard/finance/coupons/apply` (`CouponRedemptionRecordDto`). */
export type CouponRedemption = Schemas["CouponRedemptionRecordDto"]

/* ─── Query ─── */

export interface CouponListQuery extends PaginatedQuery {
  search?: string
  status?: "active" | "inactive" | "expired"
}

/* ─── Payloads (mirror the request DTOs) ─── */

/** Body of `POST /dashboard/finance/coupons` (`CreateCouponDto`). */
export type CreateCouponPayload = Schemas["CreateCouponDto"]

/** Body of `PATCH /dashboard/finance/coupons/:id` (`UpdateCouponDto`). */
export type UpdateCouponPayload = Schemas["UpdateCouponDto"]

/** Body of `POST /dashboard/finance/coupons/apply` (`ApplyCouponDto`). */
export type ApplyCouponPayload = Schemas["ApplyCouponDto"]
